#include <string.h>

int check(char *key) {
    // 假设的校验：长度 16，前 4 位为 "KZ20"，末位为前 15 位异或和
    if (strlen(key) != 16) return 0;
    unsigned char sum = 0;
    for (int i = 4; i < 15; i++) sum ^= key[i];
